actions.script:
// slot 0 is the main amount, then one slot per sub period
const newSlots = () => new Array(13).fill(null)

budgetItemsByGlId = {}
for (const curBi of budgetItemList) {
    const glAccountId = curBi.glAccountId
    let curBiList = budgetItemsByGlId[glAccountId]
    if (curBiList == null) {
        curBiList = newSlots()
        budgetItemsByGlId[glAccountId] = curBiList
    }

    const subTimePeriodId = curBi.subTimePeriodId
    if (subTimePeriodId == null) {
        curBiList[0] = curBi
    } else {
        const subPeriodIndex = (subTimePeriodIds ?? []).indexOf(subTimePeriodId)
        if (subPeriodIndex >= 0) curBiList[subPeriodIndex + 1] = curBi
    }
}

glaotpByGlId = {}
for (const curGlaotp of glaotpList) {
    const glAccountId = curGlaotp.glAccountId
    let curGltpList = glaotpByGlId[glAccountId]
    if (curGltpList == null) {
        curGltpList = newSlots()
        glaotpByGlId[glAccountId] = curGltpList
    }

    const subPeriodIndex = (allTimePeriodIds ?? []).indexOf(curGlaotp.timePeriodId)
    if (subPeriodIndex >= 0) curGltpList[subPeriodIndex] = curGlaotp
}

glAccountInfoList = []
for (const glAccount of glAccountList) {
    const glAccountId = glAccount.glAccountId

    const curBiList = budgetItemsByGlId[glAccountId]
    const curGltpList = glaotpByGlId[glAccountId]

    const actualMain = curGltpList?.[0]?.postedDebits ?? null
    let amountMain = curBiList?.[0]?.amount ?? null
    if (amountMain == null && actualMain != null) amountMain = toDecimal(0)
    const infoMap = {glAccountId: glAccountId, accountCode: glAccount.accountCode, accountName: glAccount.accountName,
                     actualMain: actualMain, amountMain: amountMain}
    let subPerActualTotal = toDecimal(0)
    let subPerTotal = toDecimal(0)
    for (let i = 1; i <= subTimePeriodSize; i++) {
        const curActual = curGltpList?.[i]?.postedDebits ?? null
        let curAmount = curBiList?.[i]?.amount ?? null
        if (curAmount == null && curActual != null) curAmount = toDecimal(0)
        if (curActual != null) { infoMap['actualPer' + i] = curActual; subPerActualTotal = subPerActualTotal.add(curActual) }
        if (curAmount != null) { infoMap['amountPer' + i] = curAmount; subPerTotal = subPerTotal.add(curAmount) }
    }
    infoMap.subPerActualTotal = subPerActualTotal
    infoMap.subPerTotal = subPerTotal

    glAccountInfoList.push(infoMap)
}

// slot 0 is the main amount, then one slot per sub period
const newSlots = () => new Array(13).fill(null)
const addSorted = (map, key, value) => {
    const values = (map[key] ??= [])
    if (!values.includes(value)) values.push(value)
}

// structure BudgetItem records
budgetItemsByGlId = {}
for (const curBi of budgetItemList) {
    const glAccountId = curBi.glAccountId
    let curBiList = budgetItemsByGlId[glAccountId]
    if (curBiList == null) {
        curBiList = newSlots()
        budgetItemsByGlId[glAccountId] = curBiList
    }

    const subTimePeriodId = curBi.subTimePeriodId
    if (subTimePeriodId == null) {
        curBiList[0] = curBi
    } else {
        const subPeriodIndex = (subTimePeriodIds ?? []).indexOf(subTimePeriodId)
        if (subPeriodIndex >= 0) curBiList[subPeriodIndex + 1] = curBi
    }
}

// structure GlAccountOrgTimePeriod records
glaotpByGlId = {}
for (const curGlaotp of glaotpList) {
    const glAccountId = curGlaotp.glAccountId
    let curGltpList = glaotpByGlId[glAccountId]
    if (curGltpList == null) {
        curGltpList = newSlots()
        glaotpByGlId[glAccountId] = curGltpList
    }

    const subPeriodIndex = (allTimePeriodIds ?? []).indexOf(curGlaotp.timePeriodId)
    if (subPeriodIndex >= 0) curGltpList[subPeriodIndex] = curGlaotp
}

// structure BudgetItemDetail records
detailsByGlAssetOrFacility = {}
assetIdsByGl = {}
facilityIdsByGl = {}
for (const curBid of budgetItemDetailList) {
    const glAccountId = curBid.glAccountId
    const assetId = curBid.assetId
    const facilityId = curBid.facilityId

    let bidMapKey
    if (assetId) {
        bidMapKey = glAccountId + ':A:' + assetId
        addSorted(assetIdsByGl, glAccountId, assetId)
    } else if (facilityId) {
        bidMapKey = glAccountId + ':F:' + facilityId
        addSorted(facilityIdsByGl, glAccountId, facilityId)
    } else {
        continue
    }

    let curBidList = detailsByGlAssetOrFacility[bidMapKey]
    if (curBidList == null) {
        curBidList = newSlots()
        detailsByGlAssetOrFacility[bidMapKey] = curBidList
    }

    const subTimePeriodId = curBid.subTimePeriodId
    if (subTimePeriodId == null) {
        curBidList[0] = curBid
    } else {
        const subPeriodIndex = (subTimePeriodIds ?? []).indexOf(subTimePeriodId)
        if (subPeriodIndex >= 0) curBidList[subPeriodIndex + 1] = curBid
    }
}

// structure InvoiceItemDetail records
iiDetailsByGlAssetOrFacility = {}
for (let subPeriodIdx = 0; subPeriodIdx <= subTimePeriodSize; subPeriodIdx++) {
    const curIidtList = iidtListByPeriod[subPeriodIdx]
    for (const curIidt of curIidtList) {
        const glAccountId = curIidt.glAccountId
        const assetId = curIidt.assetId
        const facilityId = curIidt.facilityId

        let iidMapKey
        if (assetId) {
            iidMapKey = glAccountId + ':A:' + assetId
            addSorted(assetIdsByGl, glAccountId, assetId)
        } else if (facilityId) {
            iidMapKey = glAccountId + ':F:' + facilityId
            addSorted(facilityIdsByGl, glAccountId, facilityId)
        } else {
            continue
        }

        let curBidList = iiDetailsByGlAssetOrFacility[iidMapKey]
        if (curBidList == null) {
            curBidList = newSlots()
            iiDetailsByGlAssetOrFacility[iidMapKey] = curBidList
        }
        curBidList[subPeriodIdx] = curIidt
    }
}

// one row from the actuals and budget amounts, each a 13 slot list (main, then the sub periods)
const makeInfo = (baseInfo, actualList, amountList, actualField) => {
    const actualMain = actualList?.[0]?.[actualField] ?? null
    let amountMain = amountList?.[0]?.amount ?? null
    if (amountMain == null && actualMain != null) amountMain = toDecimal(0)
    const infoMap = Object.assign({}, baseInfo, {actualMain: actualMain, amountMain: amountMain})
    let subPerActualTotal = toDecimal(0)
    let subPerTotal = toDecimal(0)
    for (let i = 1; i <= subTimePeriodSize; i++) {
        const curActual = actualList?.[i]?.[actualField] ?? null
        let curAmount = amountList?.[i]?.amount ?? null
        if (curAmount == null && curActual != null) curAmount = toDecimal(0)
        if (curActual != null) { infoMap['actualPer' + i] = curActual; subPerActualTotal = subPerActualTotal.add(curActual) }
        if (curAmount != null) { infoMap['amountPer' + i] = curAmount; subPerTotal = subPerTotal.add(curAmount) }
    }
    infoMap.subPerActualTotal = subPerActualTotal
    infoMap.subPerTotal = subPerTotal
    return infoMap
}

// create detailInfoList based on glAccountList plus assets and facilities for each
detailInfoList = []
for (const glAccount of glAccountList) {
    const glAccountId = glAccount.glAccountId

    const curBiList = budgetItemsByGlId[glAccountId]
    const curGltpList = glaotpByGlId[glAccountId]
    const baseInfo = {glAccountId: glAccountId, accountCode: glAccount.accountCode, accountName: glAccount.accountName}

    if (curBiList || curGltpList) {
        detailInfoList.push(makeInfo(baseInfo, curGltpList, curBiList, 'postedDebits'))
    }

    // add asset entries to list
    for (const assetId of (assetIdsByGl[glAccountId] ?? []).sort()) {
        const curDetailKey = glAccountId + ':A:' + assetId
        detailInfoList.push(makeInfo(Object.assign({}, baseInfo, {assetId: assetId}),
                iiDetailsByGlAssetOrFacility[curDetailKey], detailsByGlAssetOrFacility[curDetailKey], 'totalAmount'))
    }

    // add facility details entries to list
    for (const facilityId of (facilityIdsByGl[glAccountId] ?? []).sort()) {
        const curDetailKey = glAccountId + ':F:' + facilityId
        detailInfoList.push(makeInfo(Object.assign({}, baseInfo, {facilityId: facilityId}),
                iiDetailsByGlAssetOrFacility[curDetailKey], detailsByGlAssetOrFacility[curDetailKey], 'totalAmount'))
    }
}
